-- signals a = 1 and b = 2 initially (type integer)
process
  variable x : integer := 1;
  variable y : integer := 2;
begin
  a <= b;  b <= a;          -- both read the OLD values
  x := y;  y := x;          -- y reads the NEW x
  wait for 0 ns;            -- let one delta cycle pass
  report "a=" & integer'image(a) & " b=" & integer'image(b) &
         " x=" & integer'image(x) & " y=" & integer'image(y);
  wait;
end process;
-- GHDL output: a=2 b=1 x=2 y=2  (signals swapped, variables did not)

entity popcount is
  port (d : in std_logic_vector(7 downto 0); n : out natural range 0 to 8);
end entity;
architecture rtl of popcount is
begin
  process (d)
    variable c : natural range 0 to 8;
  begin
    c := 0;                         -- reset on every activation
    for i in d'range loop
      if d(i) = '1' then c := c + 1; end if;
    end loop;
    n <= c;
  end process;
end architecture;

GHDL --std=08 simulation of popcount (library ieee; use ieee.std_logic_1164.all; above the entity);
d changes at 0, 10 and 20 ns and n is sampled at 5, 15 and 25 ns
@5 ns   d = x"96" = 1001 0110  ->  n = 4
@15 ns  d = x"FF" = 1111 1111  ->  n = 8
@25 ns  d = x"03" = 0000 0011  ->  n = 2
Without the line c := 0; the variable keeps its count between activations:
4 at 5 ns; at 10 ns it climbs from 4 towards 4 + 8 = 12, and the increment from
8 to 9 violates range 0 to 8 and stops the simulation with a bound-check failure.

